import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- Totals ----
    rev_tw = df["Revenue_TW"].dropna().sum()
    rev_lw = df["Revenue_LW"].dropna().sum()
    rev_ly = df["Revenue_LY"].dropna().sum()
    units_tw = df["Units_TW"].dropna().sum()
    units_lw = df["Units_LW"].dropna().sum()
    orders_tw = df["Orders_TW"].dropna().sum()
    orders_lw = df["Orders_LW"].dropna().sum()

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if df["Revenue_LY"].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": float(units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": float(units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": float(orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": float(orders_lw),
        "formula": "sum(Orders_LW)"
    })

    # ---- Total WoW % ----
    if rev_lw != 0:
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    # ---- Total YoY % ----
    if df["Revenue_LY"].notna().any() and rev_ly != 0:
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top entities by Revenue_TW ----
    top_rev = df.dropna(subset=["Revenue_TW"]).sort_values("Revenue_TW", ascending=False).head(3)
    for _, row in top_rev.iterrows():
        ent = row["Entity"]
        facts.append({
            "entity": ent, "metric": "revenue", "period": "TW",
            "value": round(float(row["Revenue_TW"]), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get("Share_Pct")):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": round(float(row["Share_Pct"]), 1),
                "formula": "Share_Pct"
            })
        if pd.notna(row.get("Rank")):
            facts.append({
                "entity": ent, "metric": "rank", "period": "TW",
                "value": float(row["Rank"]),
                "formula": "Rank"
            })

    # ---- Top WoW movers ----
    wow_df = df.dropna(subset=["WoW_Pct"]).sort_values("WoW_Pct", ascending=False).head(3)
    for _, row in wow_df.iterrows():
        facts.append({
            "entity": row["Entity"], "metric": "revenue", "period": "WoW",
            "value": round(float(row["WoW_Pct"]), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top YoY movers ----
    yoy_df = df.dropna(subset=["YoY_Pct"]).sort_values("YoY_Pct", ascending=False).head(2)
    for _, row in yoy_df.iterrows():
        facts.append({
            "entity": row["Entity"], "metric": "revenue", "period": "YoY",
            "value": round(float(row["YoY_Pct"]), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to at most 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
